const matches = $input.first().json.matches || [];
const teams = [];
for (const match of matches) {
  if (match.status !== 'FINISHED') continue;
  const homeScore = match.score?.fullTime?.home ?? 0;
  const awayScore = match.score?.fullTime?.away ?? 0;
  teams.push({
    teamId: match.homeTeam.id,
    teamName: match.homeTeam.name,
    opponentName: match.awayTeam.name,
    isHome: true,
    goalsFor: homeScore,
    goalsAgainst: awayScore,
    matchId: match.id,
    matchDate: match.utcDate,
    competition: match.competition.name
  });
  teams.push({
    teamId: match.awayTeam.id,
    teamName: match.awayTeam.name,
    opponentName: match.homeTeam.name,
    isHome: false,
    goalsFor: awayScore,
    goalsAgainst: homeScore,
    matchId: match.id,
    matchDate: match.utcDate,
    competition: match.competition.name
  });
}
return teams.map(t => ({ json: t }));

// CONFIGURE: map football-data team names to WordPress post IDs + groups.
// Team names must exactly match what football-data.org returns.
// Tip: run once and inspect "Fetch Finished Matches" output to see exact names.
// See team-config.json in this repo for the full reference structure.
const TEAM_MAP = {
  // "Exact Team Name": { postId: 0, group: "Group Name" },
  "Manchester United FC": { postId: 101, group: "Group A" },
  "Arsenal FC":           { postId: 102, group: "Group B" },
  "Chelsea FC":           { postId: 103, group: "Group B" },
  "Liverpool FC":         { postId: 104, group: "Group A" }
};
const data = $input.first().json;
const config = TEAM_MAP[data.teamName];
if (!config) {
  return [{ json: { ...data, postId: null, skip: true } }];
}
return [{ json: { ...data, postId: config.postId, group: config.group, skip: false } }];

const teamData = $('Team Lookup').first().json;
const nextMatchResp = $input.first().json;
const nextMatch = (nextMatchResp.matches || [])[0] || null;
let nextOpponent = 'TBD', nextMatchDate = null, nextCompetition = 'TBD';
if (nextMatch) {
  nextOpponent = nextMatch.homeTeam.id === teamData.teamId
    ? nextMatch.awayTeam.name
    : nextMatch.homeTeam.name;
  nextMatchDate = nextMatch.utcDate;
  nextCompetition = nextMatch.competition?.name || 'TBD';
}
const { goalsFor, goalsAgainst } = teamData;
const result = goalsFor > goalsAgainst ? 'WIN' : goalsFor < goalsAgainst ? 'LOSS' : 'DRAW';
return [{ json: { ...teamData, result, nextOpponent, nextMatchDate, nextCompetition } }];

const d = $input.first().json;
const venue = d.isHome ? 'at home' : 'away';
let nextFixture = 'No upcoming match currently scheduled.';
if (d.nextMatchDate) {
  const dt = new Date(d.nextMatchDate);
  const formatted = dt.toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' });
  nextFixture = 'Next up: ' + d.nextOpponent + ' (' + d.nextCompetition + ') on ' + formatted + '.';
}
const promptLines = [
  'You are updating the website for ' + d.teamName + '.',
  '',
  'Latest result:',
  '- Competition: ' + d.competition,
  '- Venue: ' + venue,
  '- Score: ' + d.teamName + ' ' + d.goalsFor + '-' + d.goalsAgainst + ' ' + d.opponentName,
  '- Outcome: ' + d.result,
  '- Group/Region: ' + d.group,
  '',
  'Upcoming fixture:',
  nextFixture,
  '',
  "Write a punchy, supporter-facing 2-3 sentence update for the team's website. Requirements:",
  '1. Open with the result and score',
  '2. Capture the mood (winning energy, resilience, or fighting spirit)',
  '3. Close with the next fixture to keep fans engaged',
  '',
  'Return ONLY plain text - no HTML, no markdown, no quotes.'
];
const prompt = promptLines.join('\n');
const claudeBody = {
  model: 'claude-sonnet-4-6',
  max_tokens: 256,
  messages: [{ role: 'user', content: prompt }]
};
return [{ json: { ...d, prompt, claudeBody } }];

const claudeResp = $input.first().json;
const promptData = $('Build Claude Prompt').first().json;
const generatedContent = claudeResp.content?.[0]?.text?.trim() || '';
if (!generatedContent) {
  throw new Error('Claude returned empty content for ' + promptData.teamName);
}
return [{ json: { ...promptData, generatedContent } }];

const wpPost = $input.first().json;
const teamData = $('Parse Claude Response').first().json;
const rawContent = wpPost.content?.raw || '';
const newText = teamData.generatedContent;
const START_MARKER = '<!-- wp:paragraph {"className":"match-update"} -->';
const OPEN_P = '<p class="match-update">';
const CLOSE_P = '</p>';
const END_MARKER = '<!-- /wp:paragraph -->';
let updatedContent;
const startIdx = rawContent.indexOf(START_MARKER);
if (startIdx !== -1) {
  const openPIdx = rawContent.indexOf(OPEN_P, startIdx);
  const closePIdx = rawContent.indexOf(CLOSE_P, openPIdx + OPEN_P.length);
  if (openPIdx !== -1 && closePIdx !== -1) {
    updatedContent = rawContent.substring(0, openPIdx + OPEN_P.length) + newText + rawContent.substring(closePIdx);
  } else {
    updatedContent = rawContent;
  }
} else {
  updatedContent = rawContent + '\n\n' + START_MARKER + '\n' + OPEN_P + newText + CLOSE_P + '\n' + END_MARKER;
}
const wpBody = { content: updatedContent };
return [{ json: { ...teamData, updatedContent, postSlug: wpPost.slug, wpBody } }];

const d = $('Find and Replace Block Content').first().json;
const ts = new Date().toISOString();
console.log('[' + ts + '] OK | ' + d.teamName + ' | post ' + d.postId + ' | ' + d.result + ' ' + d.goalsFor + '-' + d.goalsAgainst + ' vs ' + d.opponentName);
return [{ json: { success: true, timestamp: ts, team: d.teamName, postId: d.postId, result: d.result + ' ' + d.goalsFor + '-' + d.goalsAgainst, opponent: d.opponentName, competition: d.competition } }];
